"""Run the API: notam-schedule-api [--host 0.0.0.0] [--port 8000]
Export the contract: notam-schedule-api --export-openapi contracts/notam-api.openapi.json
"""
from __future__ import annotations

import argparse
import json
import os
import sys
from pathlib import Path

CONTRACT = Path(__file__).resolve().parents[2] / "contracts" / "notam-api.openapi.json"


def openapi_document() -> dict:
    """The contract as generated by the app (independent of credentials: uses an empty offline source)."""
    from .app import create_app
    from ..ingestion.aisweb import AiswebClient
    return create_app(AiswebClient(None, offline_dir="."), "offline", api_key="").openapi()


def main(argv: list[str] | None = None) -> int:
    p = argparse.ArgumentParser(prog="notam-schedule-api", description=__doc__,
                                formatter_class=argparse.RawDescriptionHelpFormatter)
    p.add_argument("--host", default="127.0.0.1")
    p.add_argument("--port", type=int, default=8000)
    p.add_argument("--export-openapi", metavar="FILE", nargs="?", const=str(CONTRACT),
                   help=f"write the OpenAPI contract and exit (default: {CONTRACT})")
    a = p.parse_args(argv)
    if a.export_openapi:
        Path(a.export_openapi).write_text(json.dumps(openapi_document(), ensure_ascii=False, indent=2) + "\n",
                                          encoding="utf-8")
        print(f"Contrato: {a.export_openapi}")
        return 0
    import uvicorn
    from .app import create_app
    # NOTAM_ROOT_PATH: prefix the proxy strips (e.g. /notam), so /docs and links work behind it
    uvicorn.run(create_app(), host=a.host, port=a.port, proxy_headers=True, forwarded_allow_ips="*",
                root_path=os.getenv("NOTAM_ROOT_PATH", ""))
    return 0


if __name__ == "__main__":
    sys.exit(main())
